pub fn rewrite_file(path: &str) -> Result<String, String> {
    let source = match std::fs::read_to_string(path) {
        Ok(s) => s,
        Err(e) => {
            let mut msg = String::from("read ");
            msg.push_str(path);
            msg.push_str(": ");
            msg.push_str(&e.to_string());
            return Err(msg);
        }
    };
    let next = rewrite_product_copy(&source, path);
    match std::fs::write(path, next.as_bytes()) {
        Ok(()) => Ok(next),
        Err(e) => {
            let mut msg = String::from("write ");
            msg.push_str(path);
            msg.push_str(": ");
            msg.push_str(&e.to_string());
            Err(msg)
        }
    }
}

fn walk_rewrite(root: &str, denied: &mut i32) -> Result<(), String> {
    let mut stack = Vec::new();
    stack.push(root.to_string());
    loop {
        let dir = match stack.pop() {
            Some(d) => d,
            None => break,
        };
        let rd = match std::fs::read_dir(&dir) {
            Ok(v) => v,
            Err(e) => {
                let mut msg = String::from("read_dir ");
                msg.push_str(&dir);
                msg.push_str(": ");
                msg.push_str(&e.to_string());
                return Err(msg);
            }
        };
        for ent in rd {
            let ent = match ent {
                Ok(v) => v,
                Err(e) => return Err(e.to_string()),
            };
            let path = ent.path();
            let name = path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("")
                .to_string();
            if name == ".git" || name == "target" || name == "node_modules" {
                continue;
            }
            if path.is_dir() {
                stack.push(path.to_string_lossy().into_owned());
                continue;
            }
            let ok_ext = name.ends_with(".md")
                || name.ends_with(".mjs")
                || name.ends_with(".ts")
                || name.eq_ignore_ascii_case("SKILL.md")
                || name == "skill.md";
            if ok_ext == false {
                continue;
            }
            let p = path.to_string_lossy().into_owned();
            match rewrite_file(&p) {
                Ok(_) => {}
                Err(e) => return Err(e),
            }
            let source = match std::fs::read_to_string(&p) {
                Ok(s) => s,
                Err(e) => return Err(e.to_string()),
            };
            let v = scan_product_doc(&source, &p);
            if v.allow == false {
                *denied += 1;
            }
        }
    }
    Ok(())
}

pub fn rewrite_tree(root: &str) -> Result<i32, String> {
    let mut denied = 0i32;
    match walk_rewrite(root, &mut denied) {
        Ok(()) => Ok(denied),
        Err(e) => Err(e),
    }
}


