pub mod scan_paths {
    use super::{scan_live_copy, scan_product_doc};
    use std::fs;
    use std::io::{self, Write};
    use std::path::Path;

    pub struct ScanPathsArgs {
        pub paths: Vec<String>,
    }

    pub struct ScanPaths {
        pub paths: Vec<String>,
    }

    fn write_err(msg: &str) {
        let mut err = io::stderr();
        let _ = err.write_all(msg.as_bytes());
        let _ = err.write_all(b"\n");
    }

    impl ScanPaths {
        pub fn parse(args: &[String]) -> Result<ScanPathsArgs, String> {
            let mut paths = Vec::new();
            for a in args.iter().skip(1) {
                if a.starts_with('-') {
                    continue;
                }
                if a == "rewrite" || a == "rewrite-tree" {
                    continue;
                }
                paths.push(a.clone());
            }
            if paths.is_empty() {
                return Err(String::from("scan_paths requires at least one file path"));
            }
            Ok(ScanPathsArgs { paths })
        }

        pub fn from_args(args: &ScanPathsArgs) -> Self {
            Self {
                paths: args.paths.clone(),
            }
        }

        pub fn run(&self) -> Result<i32, String> {
            let mut denied = 0i32;
            for path in &self.paths {
                let source = match fs::read_to_string(path) {
                    Ok(s) => s,
                    Err(e) => {
                        let mut msg = String::from("read ");
                        msg.push_str(path);
                        msg.push_str(": ");
                        msg.push_str(&e.to_string());
                        return Err(msg);
                    }
                };
                let file_name = Path::new(path)
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or(path);
                let verdict = if file_name == "install-plan.mjs"
                    || file_name.eq_ignore_ascii_case("README.md")
                    || file_name.eq_ignore_ascii_case("SKILL.md")
                {
                    scan_live_copy(&source)
                } else {
                    scan_product_doc(&source, path)
                };
                if verdict.allow == false {
                    denied += 1;
                    let mut msg = String::from("deny path=");
                    msg.push_str(path);
                    msg.push_str(" missing=");
                    msg.push_str(&verdict.missing.join(","));
                    msg.push_str(" banned=");
                    msg.push_str(&verdict.banned.join(","));
                    write_err(&msg);
                }
            }
            Ok(denied)
        }
    }
}

