    #[test]
    fn canonical_copy_names_live_contract() {
        must(names_live_contract(LIVE_COPY) == true);
        must(banned_live_voice(LIVE_COPY).is_empty() == true);
        must(banned_opa_live(LIVE_COPY).is_empty() == true);
        must(banned_misconfig(LIVE_COPY).is_empty() == true);
    }

    #[test]
    fn live_copy_allows_envelope_algebra() {
        let src = "Live crossing is Admit collect-all walls then Apply. Closed set does not depend on definition order.\n";
        let v = scan_live_copy(src);
        must(v.allow == true);
        must(v.missing.is_empty() == true);
        must(v.banned.is_empty() == true);
        must(names_order_independence(src) == true);
    }

    #[test]
    fn live_copy_denies_fifteen_step_voice() {
        let src = "Admit collect-all walls then Apply\n## 15-Step Evaluation Chain\n";
        let v = scan_live_copy(src);
        must(v.allow == false);
        must(v.banned.is_empty() == false);
    }

    #[test]
    fn live_copy_denies_opa_live_voice() {
        let src = "Admit collect-all walls then Apply\nAdmit collect-all then live OPA\n";
        let v = scan_live_copy(src);
        must(v.allow == false);
    }

    #[test]
    fn live_copy_denies_missing_apply() {
        let src = "Admit collect-all walls only";
        let v = scan_live_copy(src);
        must(v.allow == false);
        must(v.missing.contains(&String::from("Apply")) == true);
    }

    #[test]
    fn changelog_historical_fifteen_step_allowed() {
        let src = "- 15-step evaluation chain (Schema Builder operates BEFORE the chain)\n";
        let v = scan_product_doc(src, "CHANGELOG.md");
        must(v.allow == true);
    }

    #[test]
    fn live_skill_fifteen_step_heading_denied() {
        let src = "## 15-Step Evaluation Chain\nEvery action passes through these steps in order.\n";
        let v = scan_product_doc(src, "skill.md");
        must(v.allow == false);
    }

    #[test]
    fn lab_labeled_doc_allowed() {
        let src = "Lab evaluation-chain (not live)\nThe table below is the inherited lab runner.\n15-step evaluation chain\n";
        let v = scan_product_doc(src, "SKILL.md");
        must(v.allow == true);
    }

    #[test]
    fn misconfig_impossible_denied() {
        let src = "Admit collect-all walls then Apply. Envelope misconfig is impossible.\n";
        let v = scan_live_copy(src);
        must(v.allow == false);
        let mut scan = misconfig_claim_scan::MisconfigClaimScan::new();
        scan.source = src.to_string();
        must(scan.process().is_err() == true);
    }

    #[test]
    fn rewrite_turns_opa_into_envelope() {
        let src = "Live product path is Admit collect-all then OPA.\n";
        let out = rewrite_product_copy(src, "README.md");
        must(out.contains("Admit collect-all walls then Apply") == true);
        must(out.contains("Closed set does not depend on definition order") == true);
        must(scan_live_copy(&out).allow == true);
    }

