        let src = "Admit (AND of compiled walls, collect-all) plus live OPA on lattice-policy.rego for dynAEP wire events.\n";
        let out = rewrite_product_copy(src, "install-plan.mjs");
        must(out.contains(LIVE_COPY) == true);
